head.script:
let isFilter = false;
let isSort = false;



// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[dataList > E > onrowpositionchange]<br/>DataList 모듈에서 Row 의 선택이 변경된 후 발생합니다.",
    "validation" : [
        "DataList 모듈에서 Row 의 선택이 변경된 후 발생합니다.",
        "info 파라미터로 선택 전/후의 Row 인덱스 정보를 객체로 전달합니다.",
        "info.oldRowIndex 파라미터로 필터/정렬이 적용된 상태를 기준으로 선택되어 있던 Row 의 인덱스값을 숫자로 갖습니다.",
        "info.newRowIndex 파라미터로 필터/정렬이 적용된 상태를 기준으로 새롭게 선택될 Row 의 인덱스값을 숫자로 갖습니다.",
        "바인드 된 GridView 에서 사용자 조작, 메소드에 의해 Row 선택이 변경된 경우도 onrowpositionchange 이벤트가 발생합니다.",
        "바인드 된 GridView 에 선택된 Row 가 필터 적용 후 인덱스가 변경되면 onrowpositionchange 이벤트가 발생합니다.",
        "바인드 된 GridView 에 선택된 Row 가 필터 적용 후 표시되지 않으면 onrowpositionchange 이벤트가 발생하지 않습니다.",
        "setFilter() 메소드와 GridView 의 Header Cell 로 필터가 적용될때 모두 해당합니다.",
        "onbeforerowpositionchange 이벤트가 발생한 후 onrowpositionchange 이벤트가 발생합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {   
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        $p.data.remove("target1");
    }

    if (typeof gridView1 !== 'undefined') {
        gridView1.remove();
    }    

    // // 조건 설정       
    // let properties = {

    // };

    // let cList = $c.gcm.createCList(properties);

    // // 이벤트 설정
    // let eList = $c.gcm.createEList([""]);       

    // target 생성
    $c.gcm.createBasicDataList();

    // event 바인딩
    target1.bind("onbeforerowpositionchange", function(e){wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onbeforerowpositionchange=====");});
    target1.bind("onrowpositionchange", function(info){
        wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onrowpositionchange=====");
        wf_body_bottom.getObj("scwin").setReturnValue("info : " + info);
        wf_body_bottom.getObj("scwin").setReturnValue("info.oldRowIndex : " + info.oldRowIndex);
        wf_body_bottom.getObj("scwin").setReturnValue("info.newRowIndex : " + info.newRowIndex);
    });      

    // gridView 생성
    $c.gcm.createBasicGridView('dataList="data:target1" rowStatusVisible="true"', '', 'gridView1');

    isFilter = false;
    isSort = false;

    gridView1.setFocusedCell(1, 0, false);
}   



scwin.btn_setColumnFilter_onclick = function (e) {
    if (isFilter) {
        target1.clearFilter();  
        isFilter = false;  
    }
    else {
        target1.setColumnFilter( {type:'row', colIndex:'col1', key:"col1_2", condition:'and'})             
        target1.setColumnFilter( {type:'row', colIndex:'col1', key:"col1_4", condition:'or'})             
        isFilter = true;
    }	
};



scwin.btn_sort_onclick = function (e) {
    if (isSort) {    
        target1.clearSort();
        isSort = false;
    }
    else {
        target1.sort("col1", 1);
        isSort = true;
    }
};
